# Convert list of movies to a list of titles
movies_list = [movie['title'] for movie in movies]

st.header("Movie Recommender System")

# Dropdown for selecting a movie
selectvalue = st.selectbox("Select movie from dropdown", movies_list)

# Example of generating random feature vectors for movies (you should use actual features in a real system)
np.random.seed(42)  # For reproducibility
movie_features = np.random.rand(len(movies), 5)  # 5 features for each movie (e.g., genre, ratings)

# Compute cosine similarity between movies based on their features
similarity = cosine_similarity(movie_features)

# Recommendation function based on the similarity matrix
def recommend(movie):
    try:
        index = next(i for i, m in enumerate(movies) if m['title'] == movie)
        distance = sorted(list(enumerate(similarity[index])), reverse=True, key=lambda vector: vector[1])
        recommend_movie = []
        recommend_poster = []

        # Recommend the top 5 most similar movies (excluding the first one, which is the selected movie itself)
        for i in distance[1:6]:
            movie_data = movies[i[0]]
            recommend_movie.append(movie_data['title'])
            recommend_poster.append(fetch_poster(movie_data['imdb_id']))

        return recommend_movie, recommend_poster
    except Exception as e:
        st.error(f"An error occurred during recommendation: {e}")
        return [], []

# Button to show recommendations
if st.button("Show Recommend"):
    movie_name, movie_poster = recommend(selectvalue)
    cols = st.columns(5)
    
    for col, name, poster in zip(cols, movie_name, movie_poster):
        with col:
            st.text(name)
            if poster:
                st.image(poster, width=150)
            else:
                st.text("Poster not found")
